const $=id=>document.getElementById(id);const state={full:45,happy:60,hearts:0,sleeping:false,busy:false};let sound=false,audio;const game=document.querySelector('.game');
function render(){for(const [k,v]of [['full',state.full],['happy',state.happy]]){$(k+'Text').textContent=Math.round(v)+'%';$(k+'Bar').style.width=v+'%'}$('hearts').textContent=state.hearts;$('napLabel').textContent=state.sleeping?'일어나기':'낮잠 자기';$('mood').textContent=state.sleeping?'꿈꾸는 고양이':state.happy>=85?'행복한 고양이':'느긋한 고양이';$('level').textContent=state.hearts>=60?'집사 곁이 제일 좋아요':state.hearts>=25?'우린 꽤 친해졌어요':'우리, 알아가는 중이에요';game.classList.toggle('sleeping',state.sleeping)}
function say(t){$('bubble').textContent=t}function notes(){if(!sound)return;audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();[523.25,659.25,783.99].forEach((f,i)=>{let o=audio.createOscillator(),g=audio.createGain(),t=audio.currentTime+i*.13;o.type='sine';o.frequency.value=f;g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(.035,t+.03);g.gain.exponentialRampToValueAtTime(.001,t+.5);o.connect(g);g.connect(audio.destination);o.start(t);o.stop(t+.55)})}function hearts(){for(let i=0;i<4;i++){let p=document.createElement('span');p.className='particle';p.textContent=state.sleeping?'z':'♥';p.style.left=(44+Math.random()*15)+'%';p.style.setProperty('--drift',(Math.random()*80-40)+'px');p.style.animationDelay=i*.12+'s';$('particles').append(p);setTimeout(()=>p.remove(),2200)}}
async function act(action){if(!['meal','treat','pet','nap'].includes(action))throw Error('알 수 없는 행동이에요.');if(state.busy)return{ok:false,message:'두부가 맛있게 먹는 중이에요.'};if(state.sleeping&&action!=='nap'){say('쿨쿨… 조금만 더 쉬고 싶어.');return{ok:false,message:'먼저 두부를 깨워 주세요.'}}if(action==='nap'){state.sleeping=!state.sleeping;state.happy=Math.min(100,state.happy+3);say(state.sleeping?'집사 옆이라… 잠이 솔솔…':'잘 잤다! 집사야, 같이 놀자.');$('caption').textContent=state.sleeping?'낮잠 버튼을 누르면 두부가 일어나요':'두부를 톡 눌러 쓰다듬어 주세요';if(state.sleeping)hearts();render();return{ok:true,...state}}
if(action==='pet'){state.hearts+=3;state.happy=Math.min(100,state.happy+9);say(['고르릉… 네 손이 제일 좋아.','지금 이대로도 참 좋다냥.','집사야, 내일도 같이 있자.'][Math.floor(Math.random()*3)]);game.classList.add('purring');setTimeout(()=>game.classList.remove('purring'),1500);hearts();notes();render();return{ok:true,...state}}
if(state.full>=100){say('배가 빵빵해! 조금 쉬었다 먹자.');return{ok:false,message:'두부는 지금 배가 불러요.'}}state.busy=true;game.classList.add('eating');$('food').setAttribute('opacity','1');say(action==='meal'?'냠냠… 따뜻한 밥이 최고야!':'이건… 내가 제일 좋아하는 간식!');document.querySelectorAll('[data-action]').forEach(b=>b.disabled=true);notes();await new Promise(r=>setTimeout(r,1800));state.full=Math.min(100,state.full+(action==='meal'?23:11));state.happy=Math.min(100,state.happy+8);state.hearts+=action==='meal'?5:4;state.busy=false;game.classList.remove('eating');$('food').setAttribute('opacity','0');document.querySelectorAll('[data-action]').forEach(b=>b.disabled=false);say(state.full>=95?'잘 먹었습니다냥. 배가 아주 든든해!':'맛있다… 집사 마음까지 잘 먹었어.');hearts();render();return{ok:true,...state}}
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>act(b.dataset.action)));$('petCat').onclick=()=>act('pet');$('sound').onclick=()=>{sound=!sound;$('sound').textContent=sound?'♫ 소리 끄기':'♫ 소리 켜기';$('sound').setAttribute('aria-pressed',String(sound));notes()};setInterval(()=>{if(!state.busy){state.full=Math.max(10,state.full-.5);if(state.sleeping)state.happy=Math.min(100,state.happy+1);render()}},5000);render();
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'care_for_dubu',description:'두부에게 밥 또는 간식을 주거나, 쓰다듬거나, 낮잠 상태를 전환합니다.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['meal','treat','pet','nap']}},required:['action'],additionalProperties:false},annotations:{readOnlyHint:false},execute:input=>act(input.action)})).catch(()=>{})}catch{}}
